#!/usr/bin/env python3
"""Regenerates the generated parts of legacy-ciphers/LAWS.bend and check.bend.

  python3 gen/vectors.py           rewrite the regions between the lines
                                   "# BEGIN GENERATED by gen/vectors.py: <name>"
                                   and "# END GENERATED: <name>"
  python3 gen/vectors.py --check   only check that they are up to date

Two regions: "vectors" in LAWS.bend, the vector laws (the specifications'
test values as {==} claims), and "check" in check.bend, its main and the
expected #| lines. The expected values come from ref/model.py, the package's
independent models, which ref/gen.py checks against the specifications'
published vectors. After changing the vector laws, run gen/proof.py too: it
writes one proof per vector law. Everything outside the regions is written
by hand.
"""
import os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
PKG = os.path.join(HERE, "..")
sys.dont_write_bytecode = True
sys.path.insert(0, os.path.join(PKG, "ref"))
import model as m

h = bytes.fromhex


def lst(b):
    return "B.Octets.of_list([" + ", ".join(str(x) for x in b) + "])"


def blk128(b):
    return "M.CmBlock{%s}" % ", ".join(str(int.from_bytes(b[4 * i:4 * i + 4], "big")) for i in range(4))


def cbc(enc, key, iv, data, bs):
    out, prev = b"", iv
    for i in range(0, len(data), bs):
        prev = enc(key, bytes(a ^ b for a, b in zip(data[i:i + bs], prev)))
        out += prev
    return out


# ---------------------------------------------------------------- LAWS.bend

def vectors_region():
    out = []

    def law(name, comment, body):
        out.append("# %s\nlaw %s:\n  %s\n" % (comment, name, body))

    def v128(name, comment, mod, key_t, keyfn, key, pt, ct):
        law(name, comment, "{Result.map(&2, &2, L.LcError, %s, M.CmBlock, k => %s.encrypt(k, %s), %s(%s)) == Done{%s} : Result<&2, &2, L.LcError, M.CmBlock>}" % (key_t, mod, blk128(pt), keyfn, lst(key), blk128(ct)))

    def refusal(name, comment, key_t, keyfn, n):
        law(name, comment, "{Result.map(&2, &2, L.LcError, %s, Unit, k => Unit{}, %s(%s)) == Fail{L.LcBadKeyLength{%dn}} : Result<&2, &2, L.LcError, Unit>}" % (key_t, keyfn, lst(bytes(n)), n))

    k = h("0123456789abcdeffedcba9876543210")
    v128("sm4_gbt32907", "GB/T 32907-2016, Appendix A, example 1: key = plaintext =\n# 0123456789ABCDEFFEDCBA9876543210, ciphertext 681EDF34D206965E86B3E94F536E4246", "S.LcSm4", "S.LcSm4Key", "S.LcSm4.key", k, k, m.sm4_encrypt(k, k))
    v128("camellia_rfc3713", "RFC 3713, Appendix A: Camellia-128, key = plaintext =\n# 0123456789ABCDEFFEDCBA9876543210, ciphertext 67673138549669730857065648EABE43", "C.LcCamellia", "C.LcCamelliaKey", "C.LcCamellia.key", k, k, m.camellia_encrypt(k, k))
    z = bytes(16)
    v128("serpent_nessie", "NESSIE Serpent-128 test vectors, set 3 vector 0: the zero key and the\n# zero block, ciphertext 3620B17AE6A993D09618B8768266BAE9", "P.LcSerpent", "P.LcSerpentKey", "P.LcSerpent.key", z, z, m.serpent_encrypt(z, z))
    refusal("des_bad_key_length", "a DES key of 7 bytes is refused", "D.LcDesKey", "D.LcDes.key", 7)
    refusal("tdes_bad_key_length", "a TDEA key bundle of 8 bytes is refused (keying option 3 is not allowed)", "T.LcTdesKey", "T.LcTdes.key", 8)
    refusal("camellia_bad_key_length", "a Camellia key of 20 bytes is refused", "C.LcCamelliaKey", "C.LcCamellia.key", 20)
    refusal("serpent_bad_key_length", "a Serpent key longer than 256 bits is refused", "P.LcSerpentKey", "P.LcSerpent.key", 33)
    law("rc4_empty_key", "an empty RC4 key is refused", "{R.LcRc4.crypt(B.Octets.empty(), B.Octets.zeros(4n)) == Fail{L.LcBadKeyLength{0n}} : Result<&2, &2, L.LcError, B.Octets>}")
    law("modes64_not_whole_blocks", "the 64-bit modes refuse a message that is not whole blocks", "{Result.map(&2, &2, L.LcError, List<&2, L.LcBlock64>, Unit, bs => Unit{}, X.Lc64.blocks_of(B.Octets.zeros(12n))) == Fail{L.LcNotBlockMultiple{12n}} : Result<&2, &2, L.LcError, Unit>}")
    return "\n".join(out) + "\n"


# ---------------------------------------------------------------- check.bend

def check_region():
    lines, expect = [], []

    def out(expr, value):
        lines.append("    IO.print(%s)" % expr)
        expect.append(value)

    # DES: NIST SP 800-17, Table 1 (variable plaintext) and Table 2 (variable key)
    for k, p in [("0101010101010101", "8000000000000000"), ("0101010101010101", "4000000000000000"),
                 ("0101010101010101", "2000000000000000"), ("8001010101010101", "0000000000000000"),
                 ("4001010101010101", "0000000000000000")]:
        c = m.des_encrypt(h(k), h(p))
        out("des(%s, %s)" % (lst(h(k)), lst(h(p))), "%s %s" % (c.hex(), p.lower()))
    # TDES: SP 800-67 Rev. 1, Appendix B, all three blocks, ECB both ways; CBC too
    k = h("0123456789ABCDEF23456789ABCDEF01456789ABCDEF0123")
    pt = b"The qufck brown fox jump"
    c = b"".join(m.tdes_encrypt(k, pt[i:i + 8]) for i in range(0, 24, 8))
    out("tdes_ecb(%s, %s)" % (lst(k), lst(pt)), "%s %s" % (c.hex(), pt.hex()))
    iv = h("F69F2445DF4F9B17")
    cc = cbc(m.tdes_encrypt, k, iv, pt, 8)
    out("tdes_cbc(%s, %s, %s)" % (lst(k), lst(iv), lst(pt)), "%s %s" % (cc.hex(), pt.hex()))
    k2 = h("0123456789ABCDEF23456789ABCDEF01")
    c = b"".join(m.tdes_encrypt(k2, pt[i:i + 8]) for i in range(0, 24, 8))
    out("tdes_ecb(%s, %s)" % (lst(k2), lst(pt)), "%s %s" % (c.hex(), pt.hex()))
    # 128-bit ciphers: the specifications' vectors, both ways
    k = h("0123456789abcdeffedcba9876543210")
    out("sm4(%s, %s)" % (lst(k), lst(k)), "%s %s" % (m.sm4_encrypt(k, k).hex(), k.hex()))
    for key in ["0123456789abcdeffedcba9876543210", "0123456789abcdeffedcba98765432100011223344556677",
                "0123456789abcdeffedcba987654321000112233445566778899aabbccddeeff"]:
        out("camellia(%s, %s)" % (lst(h(key)), lst(k)), "%s %s" % (m.camellia_encrypt(h(key), k).hex(), k.hex()))
    for key in ["00" * 16, "80" + "00" * 15]:
        out("serpent(%s, %s)" % (lst(h(key)), lst(bytes(16))), "%s %s" % (m.serpent_encrypt(h(key), bytes(16)).hex(), bytes(16).hex()))
    for key in ["00" * 16, "0123456789ABCDEFFEDCBA98765432100011223344556677",
                "0123456789ABCDEFFEDCBA987654321000112233445566778899AABBCCDDEEFF"]:
        out("twofish(%s, %s)" % (lst(h(key)), lst(bytes(16))), "%s %s" % (m.twofish_encrypt(h(key), bytes(16)).hex(), bytes(16).hex()))
    # RC4: RFC 6229, the 40-bit key 0102030405, every offset it lists
    ks = m.rc4_keystream(h("0102030405"), 4112)
    for o in [0, 16, 240, 256, 496, 512, 752, 768, 1008, 1024, 1520, 1536, 2032, 2048, 3056, 3072, 4080, 4096]:
        out("B.Octets.hex(B.Octets.slice(%dn, 16n, rc4_ks(%s, 4112n)))" % (o, lst(h("0102030405"))), ks[o:o + 16].hex())
    # RC4 in pieces, and RC4-drop[1536] (RFC 4345)
    out("rc4_pieces(%s)" % lst(h("0102030405")), m.rc4_keystream(h("0102030405"), 48).hex())
    out("rc4_drop(%s)" % lst(h("0102030405")), m.rc4_keystream(h("0102030405"), 16, 1536).hex())
    # Each 128-bit cipher in cipher-modes' CBC over 32 KB (Serpent 4 KB), both ways
    big = bytes((i * 7 + 3) & 255 for i in range(32768))
    iv16 = bytes(range(16))
    for name, enc in [("sm4", m.sm4_encrypt), ("camellia", m.camellia_encrypt),
                      ("twofish", m.twofish_encrypt), ("serpent", m.serpent_encrypt)]:
        n = 32768 if name != "serpent" else 4096
        c = cbc(enc, k, iv16, big[:n], 16)
        out("%s_cbc(%s, %dn)" % (name, lst(k), n), "%s ok" % c[-16:].hex())
    c = cbc(m.tdes_encrypt, h("0123456789ABCDEF23456789ABCDEF01456789ABCDEF0123"), bytes(8), big[:16384], 8)
    out("tdes_cbc_big(%s)" % lst(h("0123456789ABCDEF23456789ABCDEF01456789ABCDEF0123")), "%s ok" % c[-8:].hex())
    # refusals
    out('show(X.Lc64.cbc_encrypt(~D.LcDesKey, ~D.LcDes.encrypt, des_key(%s), B.Octets.zeros(7n), B.Octets.zeros(8n)))' % lst(h("0101010101010101")), "bad iv 7")
    out('show(X.Lc64.ecb_encrypt(~D.LcDesKey, ~D.LcDes.encrypt, des_key(%s), B.Octets.zeros(9n)))' % lst(h("0101010101010101")), "not whole blocks 9")
    return "def main() -> IO(Unit):\n  do IO<Unit>:\n" + "\n".join(lines) + "\n\n" + "\n".join("#|" + e for e in expect) + "\n"


REGIONS = [("LAWS.bend", "vectors", vectors_region), ("check.bend", "check", check_region)]


def main():
    check = "--check" in sys.argv[1:]
    stale = False
    for fname, name, body in REGIONS:
        path = os.path.join(PKG, fname)
        with open(path, encoding="utf-8", newline="") as f:
            src = f.read()
        begin = "# BEGIN GENERATED by gen/vectors.py: %s\n" % name
        end = "# END GENERATED: %s\n" % name
        i = src.index(begin) + len(begin)
        j = src.index(end, i)
        new = src[:i] + body() + src[j:]
        if check:
            if new != src:
                print("%s differs from what gen/vectors.py generates" % fname)
                stale = True
            continue
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            f.write(new)
    if check:
        if stale:
            sys.exit(1)
        print("LAWS.bend and check.bend are up to date")


main()
